# Review package: c8a66d9..HEAD

## Commits
6dbf31f test: cover wordCount joiner rules

## Files changed
 test/topWords.test.js  |  7 +++++++
 test/wordCount.test.js | 10 ++++++++++
 2 files changed, 17 insertions(+)

## Diff
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 67e30a7..6887889 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -149,10 +149,17 @@ test('keeps hyphenated words whole', () => {

 test('returns fresh objects on every call', () => {
   const first = topWords('apple apple pear', 5);
   first[0].count = 99;
   first.push({ word: 'extra', count: 1 });
   assert.deepEqual(topWords('apple apple pear', 5), [
     { word: 'apple', count: 2 },
     { word: 'pear', count: 1 },
   ]);
 });
+
+test('drops a stray leading or trailing hyphen or apostrophe from a word', () => {
+  assert.deepEqual(topWords("dogs' dogs well- well -well", 5), [
+    { word: 'well', count: 3 },
+    { word: 'dogs', count: 2 },
+  ]);
+});
diff --git a/test/wordCount.test.js b/test/wordCount.test.js
index c1f2d6f..26a44bb 100644
--- a/test/wordCount.test.js
+++ b/test/wordCount.test.js
@@ -109,10 +109,20 @@ test('separates words at the dot in a domain name', () => {
 });

 test('counts a word written in a non-Latin script', () => {
   assert.equal(wordCount('привет'), 1);
   assert.equal(wordCount('привет мир'), 2);
 });

 test('returns 0 for text made only of punctuation', () => {
   assert.equal(wordCount('... --- !!! ?! — – / _'), 0);
 });
+
+test('splits a doubled hyphen or apostrophe into two words', () => {
+  assert.equal(wordCount('well--known'), 2);
+  assert.equal(wordCount("don''t"), 2);
+});
+
+test('counts letters and digits written together as one word', () => {
+  assert.equal(wordCount('abc123'), 1);
+  assert.equal(wordCount('3-4'), 1);
+});

